use crate::aap::caps::{http_client, notifier, state_rw};
use crate::wasi::clocks::wall_clock;

struct Node;

/// How many times the notifier is asked before the node gives up.
const NOTIFY_ATTEMPTS: u32 = 3;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Record the input this call received in the shared store.
        state_rw::put("last-input", &feed_url);

        // Clock: the time this heartbeat was taken.
        let seconds = wall_clock::now().seconds;

        // HTTPClient: the one permitted fetch. A transport failure is a value,
        // and is reported as zero characters fetched; a URL outside the
        // allowlist traps at the boundary.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        // Notifier: the contract requires `notified == true` of every output,
        // so the flag must reflect a real acceptance, never be asserted.
        let message = format!(
            "heartbeat: time={}s fetched={} chars",
            seconds, fetched
        );
        let mut notified = false;
        for _ in 0..NOTIFY_ATTEMPTS {
            if notifier::notify(&message) {
                notified = true;
                break;
            }
        }
        if !notified {
            // No output satisfying the contract can be produced honestly:
            // trap rather than emit a report that violates `ensures`.
            panic!("notifier did not accept the heartbeat notification");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
